export const BUNDLED_HUB_COMPOSE = "# Cap every container's stdout/stderr logs so they cannot fill the device disk.\n# json-file is Docker's default driver and grows unbounded without these limits.\nx-logging: &default-logging\n  driver: json-file\n  options:\n    max-size: \"10m\"\n    max-file: \"5\"\n\nservices:\n  ci-hub-db:\n    container_name: ci-hub-db\n    logging: *default-logging\n    image: postgres:14\n    pull_policy: if_not_present\n    restart: unless-stopped\n    stop_grace_period: 120s\n    volumes:\n      - ci_hub_pgdata:/var/lib/postgresql/data\n    command: -p 6543\n    ports:\n      # Loopback only: the Hub reaches Postgres over ci_hub_internal; the host\n      # port exists for local tooling and must not be offered to the LAN.\n      - \"127.0.0.1:${POSTGRES_PORT:-6543}:6543\"\n    environment:\n      POSTGRES_PASSWORD: ${POSTGRES_PASSWORD:-postgres}\n      POSTGRES_USER: companion\n      POSTGRES_DB: companiondb\n    healthcheck:\n      test: [\"CMD-SHELL\", \"pg_isready -d companiondb -U companion -p 6543\"]\n      interval: 5s\n      timeout: 20s\n      retries: 120\n    networks:\n      - ci_hub_internal\n\n  ci-hub-queue:\n    container_name: ci-hub-queue\n    logging: *default-logging\n    image: rabbitmq:4-alpine\n    pull_policy: if_not_present\n    restart: unless-stopped\n    ports:\n      # Loopback only, as for Postgres above. Nothing outside the Hub container\n      # publishes to or consumes from this broker in a deployed Hub.\n      - \"127.0.0.1:${RABBITMQ_PORT:-5001}:5672\"\n    environment:\n      RABBITMQ_DEFAULT_USER: companion\n      RABBITMQ_DEFAULT_PASS: ${RABBITMQ_PASSWORD:-admin}\n      # Disable khepri_db to speed up startup (uses classic Mnesia instead)\n      RABBITMQ_FEATURE_FLAGS: \"\"\n    healthcheck:\n      test: [\"CMD-SHELL\", \"rabbitmq-diagnostics -q check_running\"]\n      interval: 15s\n      timeout: 30s\n      retries: 20\n      start_period: 180s\n    networks:\n      # Internal only. Every installed app's main container joins ci_hub_network,\n      # so a broker on it was one leaked password away from every app being able\n      # to install, reset or uninstall anything on the Hub. Only the Hub itself\n      # needs the broker; the legacy alias stays for pre-rename RABBITMQ_HOST values.\n      ci_hub_internal:\n        aliases:\n          - ci-os-hub-queue\n\n  ci-hub:\n    # Platform selection based on DOCKER_PLATFORM env variable\n    # Set DOCKER_PLATFORM=linux/arm64 for Mac development (native ARM64 build, faster)\n    # Set DOCKER_PLATFORM=linux/amd64 for Linux production (AMD64 build, slower on Mac due to emulation)\n    platform: ${DOCKER_PLATFORM:-linux/amd64}\n    # SECURITY: the Hub container does NOT run privileged. It manages app\n    # containers by talking to the host Docker daemon over the mounted\n    # /var/run/docker.sock (see docker.service.ts — it spawns `docker compose`\n    # and uses dockerode against that socket). The daemon performs all\n    # privileged work host-side; the Hub process only needs *access* to the\n    # socket, which is granted by the entrypoint dropping to CI_HUB_CONTAINER_UID\n    # with DOCKER_GID applied via `setpriv --groups` (see docker-entrypoint.sh)\n    # + the read-only socket mount below. NOTE: the `group_add: DOCKER_GID` below\n    # only affects the brief pre-drop root phase — setpriv REPLACES the\n    # supplementary groups, so the dropped process's socket access comes solely\n    # from `--groups=$DOCKER_GID` (fed by the DOCKER_GID env var).\n    # The backend performs no iptables /\n    # modprobe / mknod / device or kernel-module operations of its own, so it\n    # needs no host devices, no extra capabilities, and no seccomp/AppArmor\n    # opt-out. `privileged: true` would grant ALL of those and directly\n    # contradict the least-privilege setup on the lines that follow, so it is\n    # intentionally omitted. If a future feature needs a specific capability,\n    # add a scoped `cap_add:` (as the tailscale sidecar does with NET_ADMIN /\n    # SYS_MODULE) rather than reintroducing blanket privilege.\n    image: ${CI_HUB_IMAGE:-ghcr.io/companionintelligence/ci-hub:latest}\n    pull_policy: if_not_present\n    depends_on:\n      ci-hub-db:\n        condition: service_healthy\n      ci-hub-queue:\n        condition: service_healthy\n    container_name: ci-hub\n    logging: *default-logging\n    restart: unless-stopped\n    # The container starts as root and drops to CI_HUB_CONTAINER_UID:GID in its\n    # entrypoint (docker-entrypoint.sh) after chowning bind-mount dirs the Hub must\n    # write (notably /app/tunnel — Docker creates missing bind sources root-owned,\n    # which otherwise wedges the tunnel token as `tunnel_token_missing`). This\n    # replaces a compose `user:` directive, which cannot chown the dir first.\n    # The desktop app writes CI_HUB_CONTAINER_UID/GID/DOCKER_GID to the env file\n    # from resolve_hub_container_identity(): 0:0 on Windows (Docker Desktop / NTFS\n    # bind mounts require root — the entrypoint then skips the drop), or the host\n    # UID:GID on Linux/macOS.\n    # Host docker.sock is root:docker (660); add the host docker group GID (see init-hub-data-dirs.ts).\n    group_add:\n      - \"${DOCKER_GID:-973}\"\n    ports:\n      - \"${API_PORT:-5002}:5002\"\n    healthcheck:\n      start_period: 90s\n      test: [\"CMD\", \"curl\", \"-f\", \"http://localhost:5002/api/health/live\"]\n      interval: 10s\n      timeout: 5s\n      retries: 15\n    volumes:\n      # Data directories — bind mounts from host (require ROOT_FOLDER_HOST)\n      - ${ROOT_FOLDER_HOST:-.internal}/media:/data/media\n      # Allow Hub to configure Tunnel — resolves to the sibling tunnel/ directory\n      # relative to ROOT_FOLDER_HOST (e.g. /home/user/ci-hub/.internal → /home/user/ci-hub/tunnel).\n      # Must match scripts/heal-hub-bind-mounts.ts resolveTunnelDir() (= <ROOT_FOLDER_HOST>/../tunnel),\n      # which pre-creates/repairs this dir owned by the container UID. A plain\n      # ${ROOT_FOLDER_HOST}/tunnel bind would land inside .internal, where the heal step never\n      # runs, so Docker auto-creates it root-owned and the Hub can't write the tunnel token.\n      - ${ROOT_FOLDER_HOST:-.internal}/../tunnel:/app/tunnel\n      - ${ROOT_FOLDER_HOST:-.internal}/app-data:/app-data\n      - ${ROOT_FOLDER_HOST:-.internal}/state:/data/state\n      - ${ROOT_FOLDER_HOST:-.internal}/repos:/data/repos\n      - ${ROOT_FOLDER_HOST:-.internal}/apps:/data/apps\n      - ${ROOT_FOLDER_HOST:-.internal}/logs:/data/logs\n      - ${ROOT_FOLDER_HOST:-.internal}/user-config:/data/user-config\n      - ${ROOT_FOLDER_HOST:-.internal}/backups:/data/backups\n      # Static. Long syntax with create_host_path:false so a mis-resolved host path\n      # fails loudly (\"bind source path does not exist\") instead of Docker silently\n      # creating an empty dir here — which would mount a directory over /data/.env\n      # and crash the backend with EISDIR. (Seen when ROOT_FOLDER_HOST used the\n      # Docker-Desktop `/c/...` form against a native WSL2 engine that needs `/mnt/c/...`.)\n      - type: bind\n        source: ${ENV_FILE:-.env}\n        target: /data/.env\n        bind:\n          create_host_path: false\n      # Backend uses DATA_DIR/cache (/data/cache). Created by scripts/init-hub-data-dirs.ts.\n      - ${ROOT_FOLDER_HOST:-.internal}/cache:/data/cache\n      - ${DOCKER_SOCKET_PATH:-/var/run/docker.sock}:/var/run/docker.sock:ro\n      # Container-safe Docker config — scripts/init-docker-config.ts writes\n      # ${ROOT_FOLDER_HOST}/.docker/config.json (whole dir mounted for non-root Hub).\n      - ${ROOT_FOLDER_HOST:-.internal}/.docker:/data/.docker\n      - /proc/meminfo:/host/proc/meminfo:ro\n      - ${COMPOSE_FILE_HOST:-./docker-compose.prod.yml}:/data/docker-compose.yml\n      - /etc/localtime:/etc/localtime:ro\n      - /etc/timezone:/etc/timezone:ro\n      - /etc/machine-id:/etc/machine-id:ro\n      # Hub Pool needs this node's Tailscale identity: `nodeFqdn` is how a peer\n      # addresses us, and TailscaleService.resolveStrategy() can only get it by\n      # running the host's CLI against the host's tailscaled socket. Neither was\n      # mounted, so on every Tailscale host the Hub reported `notInstalled`,\n      # `/inference/pool/identify` returned `nodeFqdn: null`, and pairing could\n      # never complete. The `hub-tailscale` sidecar below is not a substitute --\n      # it sits behind the `private-vpn` profile and needs TAILSCALE_AUTHKEY.\n      #\n      # The socket is mounted READ-WRITE deliberately: isSocketAvailable() probes\n      # it with R_OK|W_OK, and the tailscaled protocol writes. A `:ro` mount here\n      # looks right and silently defeats the whole thing.\n      #\n      # Both are optional by design. On a host with no Tailscale, Docker creates\n      # empty paths, the socket probe fails, and the Hub degrades to exactly the\n      # no-VPN behaviour it has today -- so this is safe on every host. Override\n      # the source paths where the distro puts them elsewhere.\n      - ${TAILSCALE_SOCKET_DIR:-/var/run/tailscale}:/var/run/tailscale\n      - ${TAILSCALE_BINARY:-/usr/bin/tailscale}:/usr/bin/tailscale:ro\n    extra_hosts:\n      - \"host.docker.internal:host-gateway\"\n    # Resolver patience (#933): the Hub resolves sibling containers (ci-hub-db, ci-hub-queue,\n    # per-app services) through Docker's embedded DNS, which drops queries under network churn —\n    # every app install/uninstall recreates networks. Default musl/glibc behavior gives up after\n    # 2 attempts and surfaces getaddrinfo EAI_AGAIN. Retry harder before failing.\n    dns_opt:\n      - attempts:5\n      - timeout:2\n    networks:\n      # The gateway network, as for traefik below: ci_hub_internal sorts first\n      # by name and would otherwise take the default route. The Hub's own\n      # connections (the Portal, image registries) would then leave from that\n      # bridge, whose range Docker picked when it was created and which a VPN\n      # or an accepted Tailscale route may also claim. Postgres and RabbitMQ\n      # are still reached over ci_hub_internal.\n      ci_hub_network:\n        gw_priority: 1\n        aliases:\n          - ci-os-hub\n          - host.docker.internal\n      ci_os_hub_network:\n        aliases:\n          - ci-os-hub\n          - host.docker.internal\n      ci_hub_internal:\n    environment:\n      # Runtime marker: if absent, a new image detects the pre-rename compose\n      # from its legacy queue host and keeps writing ci-os-hub DNS/network names.\n      HUB_CONTAINER_NAME: ci-hub\n      # The two edge hops' fixed addresses, for Traefik's trusted-forwarders\n      # list (written into traefik.yml at config-copy time) and the Hub's own\n      # (ProxyTrustService). By address, never the edge subnet: its gateway is\n      # where every connection that reaches Traefik through the host comes\n      # from. Must match the cloudflared and hub-tailscale addresses below.\n      HUB_EDGE_CLOUDFLARED_IP: ${HUB_EDGE_CLOUDFLARED_IP:-10.128.0.3}\n      HUB_EDGE_TAILSCALE_IP: ${HUB_EDGE_TAILSCALE_IP:-10.128.0.4}\n      # Traefik's own edge address, for the Hub to attach a Traefik created\n      # before the edge network existed when it starts cloudflared (which is on\n      # the edge network only). Must match the traefik address below.\n      HUB_EDGE_TRAEFIK_IP: ${HUB_EDGE_TRAEFIK_IP:-10.128.0.2}\n      # `tailscale serve` upstream for the sidecar: Traefik's fixed edge\n      # address rather than the name `traefik`, which the sidecar (on three\n      # networks) could resolve to an address Traefik does not trust. Must\n      # match HUB_EDGE_TRAEFIK_IP. Only a fallback: the Private VPN sync names\n      # each app's container and the Hub itself as the upstream, so no\n      # current publish goes through Traefik.\n      TAILSCALE_SERVE_UPSTREAM: ${TAILSCALE_SERVE_UPSTREAM:-10.128.0.2:80}\n      OLLAMA_URL: http://host.docker.internal:11434\n      VLLM_URL: ${VLLM_URL:-http://host.docker.internal:8000}\n      # Empty unless the operator sets it: the Hub then probes oMLX's default\n      # (host.docker.internal:8000) only on Apple Silicon. A default here would\n      # skip that gate and probe vLLM's :8000 as oMLX on every Linux node.\n      OMLX_URL: ${OMLX_URL:-}\n      VLLM_API_KEY: ${VLLM_API_KEY:-}\n      OMLX_API_KEY: ${OMLX_API_KEY:-}\n      LEMONADE_URL: ${LEMONADE_URL:-http://host.docker.internal:13305}\n      API_PORT: 5002\n      CI_HUB_ENVIRONMENT: ${CI_HUB_ENVIRONMENT:-production}\n      LOCAL: ${LOCAL:-false}\n      NODE_ENV: ${NODE_ENV:-production}\n      NODE_OPTIONS: ${NODE_OPTIONS:---disable-warning=ExperimentalWarning}\n      HOME: /data/user-config\n      ROOT_FOLDER_HOST: ${ROOT_FOLDER_HOST:?ROOT_FOLDER_HOST must be set to an absolute host path}\n      DOCKER_CONFIG: /data/.docker\n      # Passed through EMPTY, not defaulted to 1000, so the entrypoint's own derivation is\n      # authoritative. `docker-entrypoint.sh` picks the owner of /data when this is unset —\n      # 1000 for a user-owned install, 0 for a root-owned one, where it then skips the\n      # privilege drop. Defaulting here made the variable ALWAYS set, so that derivation was\n      # dead code on the only path that matters, and a root-owned install crash-looped on\n      # EACCES reading its own 0600 /data/.env.\n      # Compose renders `${VAR:-}` as the empty string rather than omitting the key, and the\n      # image's BusyBox `sh` treats an empty value as unset for `${VAR:-default}` — both\n      # verified against the shipped image, because the whole fix rests on them.\n      CI_HUB_CONTAINER_UID: ${CI_HUB_CONTAINER_UID:-}\n      CI_HUB_CONTAINER_GID: ${CI_HUB_CONTAINER_GID:-}\n      # Consumed by docker-entrypoint.sh to keep Docker-socket access after it\n      # drops privileges (matches the group_add below).\n      DOCKER_GID: ${DOCKER_GID:-973}\n      POSTGRES_HOST: ci-hub-db\n      POSTGRES_PASSWORD: ${POSTGRES_PASSWORD:-postgres}\n      POSTGRES_USERNAME: companion\n      POSTGRES_DBNAME: companiondb\n      POSTGRES_PORT: 6543\n      RABBITMQ_USERNAME: companion\n      RABBITMQ_PASSWORD: ${RABBITMQ_PASSWORD:-admin}\n      RABBITMQ_HOST: ci-hub-queue\n      RABBITMQ_PORT: 5672\n      INTERNAL_IP: ${INTERNAL_IP:-127.0.0.1}\n      CI_HUB_VERSION: ${CI_HUB_VERSION:-0.2.27}\n      LOG_LEVEL: ${LOG_LEVEL:-info}\n      # CI_CLOUD_URL comes from env_file + /data/.env mount only — do not set it here;\n      # compose `environment:` interpolates from the host shell and overrides env_file.\n    env_file:\n      - path: ${ENV_FILE:-.env}\n        required: false\n    labels:\n      traefik.enable: true\n      ci-hub.managed: true\n      ci-os-hub.managed: true\n      # The image exposes both the dev (3000) and prod (5002) API ports. Pin\n      # Traefik to the canonical network and prod port instead of letting its\n      # Docker provider choose an arbitrary network/first exposed port.\n      traefik.docker.network: \"ci-hub_network\"\n      traefik.http.middlewares.ci-hub.forwardauth.address: \"http://ci-hub:5002/api/auth/traefik\"\n      # false: decide from the request the router matched, never from forwarded\n      # headers that arrived with it (see assets/traefik/dynamic/dynamic.yml).\n      traefik.http.middlewares.ci-hub.forwardauth.trustForwardHeader: \"false\"\n      # Every signed identity header must ride through — Traefik copies ONLY the headers\n      # listed here onto the forwarded request, and consumers verifying the signature fail\n      # closed on a missing timestamp/signature (CI-Engineering#74). Listing a name also strips\n      # a visitor's own copy, which keeps the stable-id trio from ever arriving unsigned.\n      traefik.http.middlewares.ci-hub.forwardauth.authResponseHeaders: \"X-CI-Hub-User,X-CI-Hub-User-Timestamp,X-CI-Hub-User-Signature,X-CI-Hub-User-Issuer,X-CI-Hub-User-Id,X-CI-Hub-User-Id-Signature\"\n      # Prevent Traefik from creating a default router on websecure (which triggers ACME)\n      traefik.http.routers.ci-hub.entrypoints: \"web\"\n      traefik.http.routers.ci-hub.rule: \"Host(`ci-hub.local`)\"\n      traefik.http.routers.ci-hub.service: \"ci-hub\"\n      traefik.http.routers.ci-os-hub.entrypoints: \"web\"\n      traefik.http.routers.ci-os-hub.rule: \"Host(`ci-os-hub.local`)\"\n      traefik.http.routers.ci-os-hub.service: \"ci-hub\"\n      traefik.http.services.ci-hub.loadbalancer.server.port: \"5002\"\n\n  traefik:\n    image: traefik:v3.6.7\n    pull_policy: if_not_present\n    container_name: traefik\n    logging: *default-logging\n    restart: unless-stopped\n    command:\n      - --configfile=/etc/traefik/traefik.yml\n    ports:\n      - \"${HTTP_PORT:-80}:80\"\n      - \"${HTTPS_PORT:-443}:443\"\n      - \"${TRAEFIK_DASHBOARD_PORT:-8080}:8080\"  # Dashboard\n    volumes:\n      - ${DOCKER_SOCKET_PATH:-/var/run/docker.sock}:/var/run/docker.sock:ro\n      # Mount Traefik config files individually to avoid mount conflicts.\n      # create_host_path:false: fail loudly if the host path is mis-resolved rather\n      # than letting Docker fabricate an empty dir over traefik.yml (crash-loops\n      # Traefik with \"traefik.yml: is a directory\").\n      - type: bind\n        source: ${ROOT_FOLDER_HOST:-.internal}/state/traefik/config/traefik.yml\n        target: /etc/traefik/traefik.yml\n        read_only: true\n        bind:\n          create_host_path: false\n      - ${ROOT_FOLDER_HOST:-.internal}/state/traefik/dynamic:/etc/traefik/dynamic:ro\n      # acme.json is a FILE mount like traefik.yml above — same create_host_path:false\n      # guard, or a mis-resolved path silently becomes a persistent host directory\n      # that breaks ACME issuance until manually deleted.\n      - type: bind\n        source: ${ROOT_FOLDER_HOST:-.internal}/state/traefik/acme_storage.json\n        target: /etc/traefik/acme.json\n        bind:\n          create_host_path: false\n      - ${ROOT_FOLDER_HOST:-.internal}/state/traefik/tls:/etc/traefik/tls:ro\n    networks:\n      # The gateway network, as it was before the edge network existed: the\n      # edge sorts first by name and would otherwise take the default route, so\n      # Traefik's own connections to the host (a port-expose app's\n      # host.docker.internal upstream) would leave from 10.128.0.2 — outside\n      # the 172.16.0.0/12 that fleet ufw rules admit from Docker bridges.\n      # `gw_priority` needs Compose 2.33+ and Engine 28+; Docker 29 ships both.\n      # The desktop app and `cihub up` check both before they start the stack.\n      ci_hub_network:\n        gw_priority: 1\n      ci_os_hub_network:\n      # Fixed address on the edge network, where cloudflared and the Tailscale\n      # sidecar reach it by this address alone. See `ci_hub_edge` below.\n      ci_hub_edge:\n        ipv4_address: ${HUB_EDGE_TRAEFIK_IP:-10.128.0.2}\n    extra_hosts:\n      - \"host.docker.internal:host-gateway\"\n    depends_on:\n      - ci-hub\n    labels:\n      ci-hub.managed: true\n      ci-os-hub.managed: true\n\n  # Cloudflare tunnel — opt-in. Requires a token file at ./tunnel/token.\n  # Enable with: docker compose --profile cloudflare up -d cloudflared\n  cloudflared:\n    image: cloudflare/cloudflared:2026.2.0\n    pull_policy: if_not_present\n    container_name: cloudflared\n    logging: *default-logging\n    restart: unless-stopped\n    command: tunnel run --token-file /home/nonroot/.cloudflared/token\n    volumes:\n      # Sibling tunnel/ dir (see ci-hub /app/tunnel mount above) — where the Hub writes the token.\n      - ${ROOT_FOLDER_HOST:-.internal}/../tunnel:/home/nonroot/.cloudflared:ro\n    # The edge network ONLY, at a fixed address. Every app's tunnel ingress\n    # targets `traefik:80`, and Docker DNS resolves that to the one address the\n    # two share, so every tunnelled app request reaches Traefik from this\n    # address — the one Traefik trusts forwarded headers from. A second shared\n    # network would let DNS answer with an address Traefik does not trust.\n    networks:\n      ci_hub_edge:\n        ipv4_address: ${HUB_EDGE_CLOUDFLARED_IP:-10.128.0.3}\n    # Load-bearing: Portal routes the Hub's OWN hostname to\n    # http://host.docker.internal:{hub port} (rebuilt from its database, not\n    # from the Hub's sync), which reaches the Hub's published port through the\n    # host. That works from a bridge the Hub is not on (checked on the fleet's\n    # Docker 29.8); the Hub sees it from a bridge gateway and ignores its\n    # forwarded headers, as before this network existed.\n    extra_hosts:\n      - \"host.docker.internal:host-gateway\"\n    depends_on:\n      - ci-hub\n      - traefik\n    profiles:\n      - cloudflare\n\n  # --- Private VPN (Tailscale sidecar) -----------------------------------------\n  # Profile `private-vpn`. The `hub-tailscale` container joins your tailnet via\n  # tailscale.com using TS_AUTHKEY (set TAILSCALE_AUTHKEY in `.env`; HEADSCALE_PREAUTH_KEY is still read as a fallback for old configs).\n  # Advertises the Docker bridge by default so tailnet devices can reach the Hub network.\n  hub-tailscale:\n    image: tailscale/tailscale:v1.98.3\n    pull_policy: if_not_present\n    container_name: hub-tailscale\n    logging: *default-logging\n    restart: unless-stopped\n    hostname: hub-tailscale\n    entrypoint:\n      - /bin/sh\n      - -lc\n      - |\n        if [ -n \"${TAILSCALE_AUTHKEY:-}\" ]; then\n          export TS_AUTHKEY=\"$TAILSCALE_AUTHKEY\"\n          exec /usr/local/bin/containerboot\n        fi\n        # No auth key: run tailscaled alone. containerboot would run `tailscale up`\n        # itself, kill it after 60 s (nobody can finish an interactive login in\n        # here) and exit; `restart: unless-stopped` then respawns it every minute,\n        # and every respawn re-creates the container's veth on the host, which\n        # the host's browsers see as a network change (Chrome: ERR_NETWORK_CHANGED).\n        # Hub runs `tailscale up` over `docker exec` and shows the auth URL, so\n        # the sidecar only has to keep the daemon alive. A persisted login is\n        # resumed by tailscaled by itself; the tun node is what containerboot\n        # would have created. `$$` keeps compose from interpolating the shell vars.\n        if [ ! -c /dev/net/tun ]; then\n          mkdir -p /dev/net && mknod /dev/net/tun c 10 200\n        fi\n        exec tailscaled --socket=\"$$TS_SOCKET\" --statedir=\"$$TS_STATE_DIR\"\n    cap_add:\n      - NET_ADMIN\n      - SYS_MODULE\n    environment:\n      TAILSCALE_AUTHKEY: ${TAILSCALE_AUTHKEY:-${HEADSCALE_PREAUTH_KEY:-}}\n      # During the ci-os-hub → ci-hub transition, an upgraded appliance has\n      # the legacy bridge on 172.18/16 and the canonical bridge on 172.19/16.\n      # Fresh installs create the same two bridges in the opposite order.\n      TS_EXTRA_ARGS: ${HUB_TAILSCALE_EXTRA_ARGS:---login-server=https://controlplane.tailscale.com --accept-routes --advertise-routes=172.18.0.0/16,172.19.0.0/16}\n      TS_STATE_DIR: /var/lib/tailscale\n      TS_USERSPACE: \"false\"\n      TS_SOCKET: /var/run/tailscale/tailscaled.sock\n    volumes:\n      - hub_tailscale_state:/var/lib/tailscale\n    networks:\n      # The gateway network, as for traefik: not the edge, which sorts first.\n      ci_hub_network:\n        gw_priority: 1\n      ci_os_hub_network:\n      # Fixed address on the edge network: `tailscale serve` is pointed at\n      # Traefik's edge address (TAILSCALE_SERVE_UPSTREAM on the ci-hub service),\n      # so tailnet visitors reach Traefik from an address it trusts.\n      ci_hub_edge:\n        ipv4_address: ${HUB_EDGE_TAILSCALE_IP:-10.128.0.4}\n    healthcheck:\n      # Passes as soon as tailscaled is accepting commands (any BackendState).\n      # grep for \"BackendState\" in the JSON output — present whenever the daemon\n      # is up, even if not yet authenticated (NeedsLogin / NoState).\n      test: [\"CMD-SHELL\", \"tailscale status --json 2>&1 | grep -q 'BackendState'\"]\n      interval: 5s\n      timeout: 5s\n      retries: 12\n      start_period: 10s\n    labels:\n      ci-hub.managed: true\n      ci-os-hub.managed: true\n    profiles:\n      - private-vpn\n\nnetworks:\n  ci_hub_network:\n    driver: bridge\n    name: ci-hub_network\n  # Hub-private plumbing: Postgres and RabbitMQ live here and only the Hub\n  # joins it. Apps never see this network — it is not offered to app containers\n  # by the compose builder — so the Hub's own infrastructure is unreachable from\n  # a marketplace container by design rather than by password.\n  ci_hub_internal:\n    driver: bridge\n    name: ci-hub_internal\n  # The edge: Traefik plus the two proxies that carry public traffic to it,\n  # cloudflared and the Tailscale sidecar, on a bridge with a FIXED subnet and\n  # fixed addresses. That is what lets Traefik trust the client address those\n  # two forward (traefik.yml `forwardedHeaders.trustedIPs`) while stripping it\n  # from everything else, and what lets the Hub and each app trust Traefik's\n  # hop in turn (ProxyTrustService). Trust is by those two addresses, never\n  # the subnet: its .1 is the bridge gateway, the host's own address on it, so\n  # anything the host sends or routes onto the bridge arrives from there.\n  #\n  # Nothing may join it at an address Docker picks. `ip_range` is the pool\n  # Docker allocates from, and this one holds only the network address and the\n  # gateway, so every member needs a fixed address outside it and anything\n  # else — a container started with `--network ci-hub_edge`, or an app whose\n  # `network_mode` names this network (which the Hub also refuses) — fails to\n  # start with \"no available IPv4 addresses\" instead of taking a hop's address.\n  # Measured on Docker 29.8: fixed members start; a dynamic one is refused.\n  #\n  # The subnet is inside the 10.128.0.0–10.128.9.0 range reserved for Hub\n  # infrastructure, so the app allocator never hands it out; override\n  # HUB_EDGE_SUBNET, HUB_EDGE_IP_RANGE and the three HUB_EDGE_*_IP values\n  # together if it collides with something on your LAN. Compose recreates the\n  # network when these change, but reconnects running members WITHOUT their\n  # fixed addresses (Compose 5.5.1), so they then fail to start: follow such a\n  # change with `up -d --force-recreate traefik cloudflared hub-tailscale`.\n  ci_hub_edge:\n    driver: bridge\n    name: ci-hub_edge\n    ipam:\n      config:\n        - subnet: ${HUB_EDGE_SUBNET:-10.128.0.0/29}\n          ip_range: ${HUB_EDGE_IP_RANGE:-10.128.0.0/31}\n  # Keep the retired network so already-installed apps stay attached and can\n  # still resolve the Hub via the ci-os-hub alias on this network.\n  ci_os_hub_network:\n    driver: bridge\n    name: ci-os-hub_network\n\nvolumes:\n  ci_hub_pgdata:\n    name: ci_hub_pgdata\n  hub_tailscale_state:\n    name: hub_tailscale_state\n";

/** packages/backend/assets/traefik/traefik.yml */
export const BUNDLED_TRAEFIK_YML = "api:\n  dashboard: true\n  # SECURITY: keep the insecure API/dashboard OFF by default. When `insecure` is\n  # true, Traefik serves the unauthenticated dashboard + API on :8080, which the\n  # prod compose publishes to the host — an unauthenticated control-plane leak.\n  # It is only re-enabled for local development at config-copy time (see\n  # AppService.copyAssets); production/staging/test all keep it disabled.\n  insecure: false\n\nproviders:\n  docker:\n    endpoint: \"unix:///var/run/docker.sock\"\n    watch: true\n    exposedByDefault: false\n    # Disable host information retrieval to avoid Docker API version errors\n    useBindPortIP: false\n  file:\n    directory: /etc/traefik/dynamic\n    watch: true\n\n# Which peers may vouch for a client's address. ONLY the two edge hops,\n# cloudflared and the Tailscale sidecar, at the fixed addresses\n# docker-compose.prod.yml gives them on `ci_hub_edge`. A request from anywhere\n# else — the LAN, an app container, the host — has its forwarded headers\n# stripped and is named as the client itself, so nothing else can choose the\n# address it appears as.\n#\n# By address, NOT the edge subnet: the subnet's gateway (.1) is the host's own\n# address on the bridge, so anything the host sends or routes onto it arrives\n# from there — every connection to Traefik's published ports, whenever the edge\n# is Traefik's gateway network, including an app dialling\n# host.docker.internal:80. See `resolveEdgeHops`.\n#\n# The values are the compose defaults, real addresses rather than placeholders\n# because the CLI and the desktop app seed this file with nothing but the ACME\n# email filled in, and Traefik will not start on an entry that is not an\n# address. The Hub rewrites each tagged line from HUB_EDGE_CLOUDFLARED_IP /\n# HUB_EDGE_TAILSCALE_IP at config-copy time (AppService.copyAssets), and\n# restarts Traefik when that changes the file, since Traefik reads this file\n# only at startup. Keep the `# edge hop:` tags.\n#\n# Trusting a hop keeps EVERY forwarded header it sends, and Traefik fills in\n# only those left empty. Cloudflare rewrites X-Forwarded-For and\n# X-Forwarded-Proto but passes the visitor's own X-Real-Ip, X-Forwarded-Uri\n# and the like through, so tunnel routes strip those first\n# (`ci-hub-edge-headers` in dynamic/dynamic.yml), and the Hub's forward auth\n# reads the request the router matched, not the forwarded headers.\nentryPoints:\n  web:\n    address: \":80\"\n    # Allow plain HTTP - no automatic redirect to HTTPS\n    # Cloudflare Tunnel connects via plain HTTP\n    forwardedHeaders:\n      trustedIPs:\n        - 10.128.0.3/32 # edge hop: cloudflared\n        - 10.128.0.4/32 # edge hop: hub-tailscale\n    transport:\n      respondingTimeouts:\n        readTimeout: 300s\n        writeTimeout: 300s\n        idleTimeout: 300s\n  websecure:\n    address: \":443\"\n    http:\n      tls:\n        certResolver: myresolver\n    forwardedHeaders:\n      trustedIPs:\n        - 10.128.0.3/32 # edge hop: cloudflared\n        - 10.128.0.4/32 # edge hop: hub-tailscale\n    transport:\n      respondingTimeouts:\n        readTimeout: 300s\n        writeTimeout: 300s\n        idleTimeout: 300s\n\ncertificatesResolvers:\n  myresolver:\n    acme:\n      email: {{ACME_EMAIL}}\n      storage: /etc/traefik/acme.json\n      httpChallenge:\n        entryPoint: web\n\nlog:\n  level: INFO\n  # Suppress Docker provider errors about host information retrieval\n  format: json\n";

/** packages/backend/assets/traefik/dynamic/dynamic.yml */
export const BUNDLED_TRAEFIK_DYNAMIC_YML = "# Transport security floor for every TLS router Traefik serves (Hub itself and\n# every app behind it, CI Memory included). Go's crypto/tls already defaults to\n# this and has no SSLv2/SSLv3 at all, but the floor is pinned here so it is a\n# stated configuration rather than an inherited default, and so an upgrade of\n# Traefik or Go can never lower it silently.\ntls:\n  options:\n    default:\n      minVersion: VersionTLS12\n\nhttp:\n  serversTransports:\n    insecuretransport:\n      insecureSkipVerify: true\n\n  middlewares:\n    ci-hub:\n      forwardAuth:\n        address: \"http://{{HUB_CONTAINER_NAME}}:5002/api/auth/traefik\"\n        # false: the Hub decides from the request the router matched — its Host\n        # (the tunnel's rewritten origin host), URI and method — never from\n        # X-Forwarded-* headers that arrived with it. The entry points trust\n        # cloudflared's forwarded headers (traefik.yml), and Cloudflare passes a\n        # visitor's own X-Forwarded-Uri / -Method / -Prefix through untouched, so\n        # with true a visitor could name a public path while requesting another,\n        # or name another app's host. The Hub still sees the peer Traefik saw.\n        trustForwardHeader: false\n        # Every signed identity header must ride through — Traefik copies ONLY the\n        # headers listed here, and consumers verifying the signature fail closed on a\n        # missing timestamp/signature (CI-Engineering#74). Listing a name also strips a\n        # visitor's own copy of it before the copy, which is what keeps the stable-id\n        # trio (issuer, id, id signature) from ever arriving unsigned.\n        authResponseHeaders:\n          - \"X-CI-Hub-User\"\n          - \"X-CI-Hub-User-Timestamp\"\n          - \"X-CI-Hub-User-Signature\"\n          - \"X-CI-Hub-User-Issuer\"\n          - \"X-CI-Hub-User-Id\"\n          - \"X-CI-Hub-User-Id-Signature\"\n\n    # First on every tunnel route (TraefikLabelsBuilder.addCloudflareLabels).\n    # Traefik keeps a trusted peer's forwarded headers and fills in only those\n    # left empty, and the entry points trust cloudflared (traefik.yml). Neither\n    # Cloudflare nor cloudflared sets these, so on a tunnel request each is\n    # whatever the visitor sent: an X-Real-Ip of their choosing would reach\n    # every app that reads it, defeating its per-address throttles. Empty\n    # removes the header; an app that needs the visitor's address reads\n    # X-Forwarded-For past HUB_TRUSTED_PROXY_CIDRS. X-Forwarded-Port is set\n    # again by the app's public-host middleware, which runs after this one.\n    ci-hub-edge-headers:\n      headers:\n        customRequestHeaders:\n          X-Real-Ip: \"\"\n          X-Forwarded-Prefix: \"\"\n          X-Forwarded-Uri: \"\"\n          X-Forwarded-Method: \"\"\n          X-Forwarded-Port: \"\"\n          X-Forwarded-Tls-Client-Cert: \"\"\n          X-Forwarded-Tls-Client-Cert-Info: \"\"\n";

/** scripts/host-probes/cihub-gpu-processes.sh */
export const BUNDLED_GPU_PROBE_SCRIPT = "#!/usr/bin/env bash\n# Write per-process GPU VRAM to the Hub's state directory, for the Hub container to read.\n#\n# The Hub runs from an Alpine image with no nvidia-smi / rocm-smi and no GPU device access, so\n# GpuProcessSamplerService cannot measure anything from inside the container on a fleet node.\n# This is the host-side writer that seam expects: the same vendor query the sampler would run,\n# written as JSON the Hub reads through /data/state/hardware/gpu_processes.json. Same shape of\n# contract as gpu_pressure.json (schemaVersion + sampledAt, stale means unmeasured).\n#\n# Usage: cihub-gpu-processes.sh [STATE_DIR]\n#   STATE_DIR defaults to $CI_HUB_STATE_PATH, else $ROOT_FOLDER_HOST/state, else\n#   ~/.local/share/companion-hub/state. The file lands in STATE_DIR/hardware/.\n#\n# Runs in well under a second; install it on a timer (see cihub-gpu-processes.timer beside this file,\n# 15 s cadence). Exit 0 with no file written when neither vendor tool is installed — the Hub then\n# reads \"unmeasured\", which is the truthful state, not \"0\". Exit 1 when a tool IS installed and its\n# query failed, so the unit shows as failed in `systemctl --user list-timers` and the journal instead\n# of the only symptom being a file that quietly went stale a minute later.\nset -euo pipefail\n\nstate_dir=\"${1:-${CI_HUB_STATE_PATH:-${ROOT_FOLDER_HOST:+$ROOT_FOLDER_HOST/state}}}\"\nstate_dir=\"${state_dir:-$HOME/.local/share/companion-hub/state}\"\nout_dir=\"$state_dir/hardware\"\nout=\"$out_dir/gpu_processes.json\"\n\nsampled_at=\"$(date -u +%Y-%m-%dT%H:%M:%SZ)\"\nvendor=\"\"\nsource=\"\"\nrows=\"\"\n\nif command -v nvidia-smi >/dev/null 2>&1; then\n  # `noheader,nounits` is load-bearing: with units the memory column reads \"6104 MiB\".\n  # Output per line: \"<pid>, <process_name>, <used_memory>\" — process_name is a full path or the\n  # process title, never containing a comma in practice; a row that does not parse is dropped.\n  if raw=\"$(nvidia-smi --query-compute-apps=pid,process_name,used_memory --format=csv,noheader,nounits 2>&1)\"; then\n    vendor=nvidia\n    source=nvidia-smi\n    rows=\"$(printf '%s\\n' \"$raw\" | awk -F', *' '\n      NF >= 3 && $1 ~ /^[0-9]+$/ && $3 ~ /^[0-9]+$/ && $3 > 0 {\n        name = $2; gsub(/\\\\/, \"\\\\\\\\\", name); gsub(/\"/, \"\\\\\\\"\", name)\n        printf \"%s{\\\"pid\\\":%d,\\\"processName\\\":\\\"%s\\\",\\\"vramMb\\\":%d}\", (n++ ? \",\" : \"\"), $1, name, $3\n      }')\"\n  else\n    echo \"nvidia-smi is installed but failed: ${raw:-no output}\" >&2\n    exit 1\n  fi\nelif command -v rocm-smi >/dev/null 2>&1; then\n  # The plain-text KFD table: PID, PROCESS NAME, GPU(s), VRAM USED (bytes), SDMA USED, CU OCCUPANCY.\n  # Header and banner rows fail the numeric-PID test; a process holding no VRAM is dropped.\n  if raw=\"$(rocm-smi --showpids 2>&1)\"; then\n    vendor=amd\n    source=rocm-smi\n    rows=\"$(printf '%s\\n' \"$raw\" | awk '\n      NF >= 4 && $1 ~ /^[0-9]+$/ && $4 ~ /^[0-9]+$/ && $4 > 0 {\n        name = $2; gsub(/\\\\/, \"\\\\\\\\\", name); gsub(/\"/, \"\\\\\\\"\", name)\n        printf \"%s{\\\"pid\\\":%d,\\\"processName\\\":\\\"%s\\\",\\\"vramMb\\\":%d}\", (n++ ? \",\" : \"\"), $1, name, int($4 / 1048576 + 0.5)\n      }')\"\n  else\n    echo \"rocm-smi is installed but failed: ${raw:-no output}\" >&2\n    exit 1\n  fi\nfi\n\nif [ -z \"$vendor\" ]; then\n  exit 0\nfi\n\nmkdir -p \"$out_dir\"\ntmp=\"$(mktemp \"$out_dir/.gpu_processes.XXXXXX\")\"\nprintf '{\"schemaVersion\":1,\"sampledAt\":\"%s\",\"source\":\"%s\",\"vendor\":\"%s\",\"processes\":[%s]}\\n' \"$sampled_at\" \"$source\" \"$vendor\" \"$rows\" > \"$tmp\"\nchmod 0644 \"$tmp\"\n# Atomic: the Hub never sees a half-written file, and a reader mid-parse keeps the old inode.\nmv -f \"$tmp\" \"$out\"\n";

/** scripts/host-probes/cihub-gpu-processes.service */
export const BUNDLED_GPU_PROBE_SERVICE = "# Per-process GPU VRAM for the Hub — see cihub-gpu-processes.sh beside this file, and the\n# \"Per-process GPU VRAM\" section of docs/fleet-setup.md for the install steps.\n[Unit]\nDescription=Write per-process GPU VRAM for the Companion Hub container\n\n[Service]\nType=oneshot\n# The state directory the Hub's compose binds to /data/state. Override with a drop-in on a node\n# whose ROOT_FOLDER_HOST is elsewhere.\nEnvironment=CI_HUB_STATE_PATH=%h/.local/share/companion-hub/state\nExecStart=%h/.local/bin/cihub-gpu-processes.sh\n";

/** scripts/host-probes/cihub-gpu-processes.timer */
export const BUNDLED_GPU_PROBE_TIMER = "[Unit]\nDescription=Sample per-process GPU VRAM for the Companion Hub every 15 s\n\n[Timer]\nOnBootSec=30s\nOnUnitActiveSec=15s\nAccuracySec=2s\n\n[Install]\nWantedBy=timers.target\n";
